(746349, 80876, 14202, '<td valign="top">Very crisp, lovely colours and great repitition.</td>', 'Very crisp, lovely colours and great repitition.', '2004-06-02 01:26:59.000000', NULL, 1),
(746351, 80103, 20210, '<td valign="top">cute!  I was trying for a similar idea but couldn''t come up with one.  great details in the setup of the pins "jumping", etc.  And technically, a strong shot too.  A real contender.  I wish the ball were more visible.</td>', 'cute!  I was trying for a similar idea but couldn''t come up with one.  great details in the setup of the pins "jumping", etc.  And technically, a strong shot too.  A real contender.  I wish the ball were more visible.', '2004-06-02 01:27:34.000000', NULL, 1),
(746353, 80261, 3599, '<td valign="top">Wow, I''m impressed.  Inside the the San Diego Padres clubhouse.  I like the uniformity with the everything.  Great shot.</td>', 'Wow, I''m impressed.  Inside the the San Diego Padres clubhouse.  I like the uniformity with the everything.  Great shot.', '2004-06-02 01:28:25.000000', NULL, 1),
(746356, 80685, 20210, '<td valign="top">well, not *much* of a team sport, and this is more a picture of a mountain than anything to do with skiing....the shot looks rather hazy, maybe a UV filter would help?  Although you get an extra point because skiing is my favorite sport. :)</td>', 'well, not *much* of a team sport, and this is more a picture of a mountain than anything to do with skiing....the shot looks rather hazy, maybe a UV filter would help?  Although you get an extra point because skiing is my favorite sport. :)', '2004-06-02 01:29:20.000000', NULL, 1),
