(746365, 80485, 20779, '<td valign="top">Ribbon!</td>', 'Ribbon!', '2004-06-02 01:32:06.000000', NULL, 1),
(746367, 80209, 20210, '<td valign="top">I wish for more color saturation here.  Or perhaps it would look better in B&amp;W with a little more contrast?  A very good shot, don''t get me wrong, but I feel like it could be a *great* shot.</td>', 'I wish for more color saturation here.  Or perhaps it would look better in B&W with a little more contrast?  A very good shot, don''t get me wrong, but I feel like it could be a *great* shot.', '2004-06-02 01:33:28.000000', NULL, 1),
