(748239, 80725, 10339, '<td valign="top">Great colors of the grass and the white fence. I am a sucker for fog shots. Nicely done.</td>', 'Great colors of the grass and the white fence. I am a sucker for fog shots. Nicely done.', '2004-06-03 02:33:54.000000', NULL, 1),
(748241, 80658, 10339, '<td valign="top">Nicely done. I like the border and the texture that you picked up on the ball.</td>', 'Nicely done. I like the border and the texture that you picked up on the ball.', '2004-06-03 02:35:07.000000', NULL, 1),
(748242, 80679, 10339, '<td valign="top">IMO you should have cropped the right edge off. There also appears to be a lot of digital noise in the image. Maybe some post-processing sharpening would have helped.</td>', 'IMO you should have cropped the right edge off. There also appears to be a lot of digital noise in the image. Maybe some post-processing sharpening would have helped.', '2004-06-03 02:38:46.000000', NULL, 1),
(748243, 80665, 10339, '<td valign="top">Very nice. I really get the sense of motion here. I like the use of the extra grain in the glove and background.</td>', 'Very nice. I really get the sense of motion here. I like the use of the extra grain in the glove and background.', '2004-06-03 02:39:32.000000', NULL, 1),
