(749007, 80787, 15207, '<td valign="top">Really interesting angle. Glad you thought about shooting this with rule of thirds/balance/composition in mind. It works well.</td>', 'Really interesting angle. Glad you thought about shooting this with rule of thirds/balance/composition in mind. It works well.', '2004-06-03 16:21:21.000000', NULL, 1),
(749008, 80384, 15207, '<td valign="top">With so many different subjects, I need just one thing (a ball or a bat) to really grab my interest. Maybe by using a shallow depth of field and doing almost a macro on a ball or a bat to then draw me into the picture would have worked better.</td>', 'With so many different subjects, I need just one thing (a ball or a bat) to really grab my interest. Maybe by using a shallow depth of field and doing almost a macro on a ball or a bat to then draw me into the picture would have worked better.', '2004-06-03 16:22:09.000000', NULL, 1),
(749009, 80720, 15207, '<td valign="top">Very very very great use of negative space. The net seems a bit pixelated, but I''m giving this a 10.</td>', 'Very very very great use of negative space. The net seems a bit pixelated, but I''m giving this a 10.', '2004-06-03 16:22:39.000000', NULL, 1),
