(750561, 79525, 20779, '<td valign="top">I really couldn''t make this fit the challenge and the photography. The branches are very pretty against the sky, but could be in better focus with more a focus subject.</td>', 'I really couldn''t make this fit the challenge and the photography. The branches are very pretty against the sky, but could be in better focus with more a focus subject.', '2004-06-04 18:56:14.000000', NULL, 1),
(750564, 80664, 20779, '<td valign="top">I like the overcast cloudiness to go with the empty field; I would like the shot better with a stronger focal interest.</td>', 'I like the overcast cloudiness to go with the empty field; I would like the shot better with a stronger focal interest.', '2004-06-04 18:57:16.000000', NULL, 1),
(750565, 80525, 20779, '<td valign="top">I like the clean simplicity of the beach scene; the small, cropped image without a strong center of interest lowered my scoring some.</td>', 'I like the clean simplicity of the beach scene; the small, cropped image without a strong center of interest lowered my scoring some.', '2004-06-04 18:58:24.000000', NULL, 1),
(750566, 80596, 20779, '<td valign="top">Nice, clean colors. I think there might be a better composition for the shot that would bring you into a more focused interest. I probably would have straightened, but maybe you did and this made a more interesting take.</td>', 'Nice, clean colors. I think there might be a better composition for the shot that would bring you into a more focused interest. I probably would have straightened, but maybe you did and this made a more interesting take.', '2004-06-04 19:00:53.000000', NULL, 1),
(750568, 80758, 20779, '<td valign="top">Love the bikes; a little blurry, but hard not to have that. The extreme crop and there being the "players" as one of the subjects in the shot lowered my score a bit.</td>', 'Love the bikes; a little blurry, but hard not to have that. The extreme crop and there being the "players" as one of the subjects in the shot lowered my score a bit.', '2004-06-04 19:02:38.000000', NULL, 1),
(750571, 80840, 20779, '<td valign="top">Great setting! The colors appear a little muddy on my monitor and I might have straightened a bit more. The movement of the yellow ball is interesting. Croquet as a team sport stretches it a bit, but I didn''t weigh that heavily in my score.</td>', 'Great setting! The colors appear a little muddy on my monitor and I might have straightened a bit more. The movement of the yellow ball is interesting. Croquet as a team sport stretches it a bit, but I didn''t weigh that heavily in my score.', '2004-06-04 19:05:12.000000', NULL, 1),
(750575, 80490, 20779, '<td valign="top">Cool shot and I like the metallic green. I know it has been validated as authentic, but it still appears a bit disjointed or "pasted in" (which I realize it isn''t -- it just makes it look somewhat flat to my eyes).</td>', 'Cool shot and I like the metallic green. I know it has been validated as authentic, but it still appears a bit disjointed or "pasted in" (which I realize it isn''t -- it just makes it look somewhat flat to my eyes).', '2004-06-04 19:07:02.000000', NULL, 1),
(750578, 80682, 20779, '<td valign="top">The colors and arrangement are great! I did score it lower due to the stretch in meeting the challenge, though.</td>', 'The colors and arrangement are great! I did score it lower due to the stretch in meeting the challenge, though.', '2004-06-04 19:07:51.000000', NULL, 1),
