INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(751189, 80849, 16301, '<td valign="top">Very nice and simple composition, the tone fits with the image. Good job...<br/> <br/>Good luck...</td>', 'Very nice and simple composition, the tone fits with the image. Good job... Good luck...', '2004-06-05 04:31:04.000000', NULL, 1),
(751191, 80384, 16301, '<td valign="top">Very nice idea and complex arrangements, or were they just thrown there? :P I like the fact that everything is dirty, it tells a story and sets a mood that way. I think this could have benefited from a slight increase in saturation to bring out the colors more. I think it would look really great in sepia with all that dirtyness in there, it would have a much more stronger mood that way. Great photo otherwise...<br/> <br/>Good luck...</td>', 'Very nice idea and complex arrangements, or were they just thrown there? :P I like the fact that everything is dirty, it tells a story and sets a mood that way. I think this could have benefited from a slight increase in saturation to bring out the colors more. I think it would look really great in sepia with all that dirtyness in there, it would have a much more stronger mood that way. Great photo otherwise... Good luck...', '2004-06-05 04:36:25.000000', NULL, 1),
(751193, 80896, 16301, '<td valign="top">Nice composition and perspective. The reflections really add to the photo. Good job...<br/> <br/>Good luck...</td>', 'Nice composition and perspective. The reflections really add to the photo. Good job... Good luck...', '2004-06-05 04:38:03.000000', NULL, 1),
(751194, 79809, 16301, '<td valign="top">I''m sure you''re getting some "I wish the ball was in focus" comments, but I really think it looks good this way, there are no rules right? Nice contrasting colors you display here, I like the off-centering of the ball. Good job...<br/> <br/>Good luck...</td>', 'I''m sure you''re getting some "I wish the ball was in focus" comments, but I really think it looks good this way, there are no rules right? Nice contrasting colors you display here, I like the off-centering of the ball. Good job... Good luck...', '2004-06-05 04:40:34.000000', NULL, 1),
(751195, 80281, 16301, '<td valign="top">Very nice and simple idea, I really like the contrasting colors. The clouds in the sky add a sense of depth. Another good idea is to throw a ball into the net, that way, the photo would have some sense of drama in it. Great job with this photo...<br/> <br/>Good luck...</td>', 'Very nice and simple idea, I really like the contrasting colors. The clouds in the sky add a sense of depth. Another good idea is to throw a ball into the net, that way, the photo would have some sense of drama in it. Great job with this photo... Good luck...', '2004-06-05 04:43:51.000000', NULL, 1),
