(752433, 80516, 14614, '<td valign="top">On of my favorites -- the brown canoe adds the interest.  The "nestled in a cove" feel creates an inviting mood.  On of my top picks this theme</td>', 'On of my favorites -- the brown canoe adds the interest.  The "nestled in a cove" feel creates an inviting mood.  On of my top picks this theme', '2004-06-06 20:14:44.000000', NULL, 1),
