(752437, 80803, 14614, '<td valign="top">I''ve played bridge and it''s no team sport :)  :)<br/> <br/>Well done shot with the high key treatment of all but the spades.  One of my favorite shots this time around</td>', 'I''ve played bridge and it''s no team sport :)  :) Well done shot with the high key treatment of all but the spades.  One of my favorite shots this time around', '2004-06-06 20:17:33.000000', NULL, 1),
(752439, 80590, 280, '<td valign="top">Hmmm, not sure about this one, although the pit crew may not class as "players"  your title is  incluing them as part of the "team" and therefore I feel that having them in the shot does go against the idea of the challenge. That said I do like the photo,  the subject is nicely framed and I like the use of B&amp;W. 7</td>', 'Hmmm, not sure about this one, although the pit crew may not class as "players"  your title is  incluing them as part of the "team" and therefore I feel that having them in the shot does go against the idea of the challenge. That said I do like the photo,  the subject is nicely framed and I like the use of B&W. 7', '2004-06-06 20:36:35.000000', NULL, 1),
(752440, 80158, 280, '<td valign="top">I don''t think the colours in the reflection work well for you here - although the top portion of the shot is quite a nice blue the bottom isn''t quite as atractive. Also the central placement of the subject and the reflections doesn''t give much interest to the shot.</td>', 'I don''t think the colours in the reflection work well for you here - although the top portion of the shot is quite a nice blue the bottom isn''t quite as atractive. Also the central placement of the subject and the reflections doesn''t give much interest to the shot.', '2004-06-06 20:41:42.000000', NULL, 1),
(752442, 80676, 280, '<td valign="top">Too busy - The background elements distract from the impact of the photograph.</td>', 'Too busy - The background elements distract from the impact of the photograph.', '2004-06-06 20:43:09.000000', NULL, 1),
(752462, 80763, 15920, '<td valign="top">Great colors on the boat.  A different angle might have been more interesting asa photo, but, to get across the idea of a racing yacht, I think you needed a view similar to this.</td>', 'Great colors on the boat.  A different angle might have been more interesting asa photo, but, to get across the idea of a racing yacht, I think you needed a view similar to this.', '2004-06-06 21:25:45.000000', NULL, 1),
(752464, 79518, 15920, '<td valign="top">A little sharper focus to get the texture of the balls would have helped.</td>', 'A little sharper focus to get the texture of the balls would have helped.', '2004-06-06 21:26:50.000000', NULL, 1),
(752465, 79525, 15920, '<td valign="top">You really needed to do something past your title in this photo to say "Golf."</td>', 'You really needed to do something past your title in this photo to say "Golf."', '2004-06-06 21:28:07.000000', NULL, 1),
