(754580, 80815, 20235, '<td valign="top">Beautiful stop-motion shot! The colors and detail are excellent..... 8</td>', 'Beautiful stop-motion shot! The colors and detail are excellent..... 8', '2004-06-08 03:40:25.000000', NULL, 1),
(754582, 80857, 3599, '<td valign="top">The halo around the ball is evident.  It is a nice photo just clean up the post-processing though.</td>', 'The halo around the ball is evident.  It is a nice photo just clean up the post-processing though.', '2004-06-08 03:42:34.000000', NULL, 1),
(754584, 80762, 3599, '<td valign="top">The border kills this one for me too distracting.  Loose it and you get a much higher score.</td>', 'The border kills this one for me too distracting.  Loose it and you get a much higher score.', '2004-06-08 03:44:06.000000', NULL, 1),
(754585, 80490, 20235, '<td valign="top">Very creative point of view. The detail, composition, and DOF are excellent and the idea overall is simply brilliant. I''m assuming the bat and ball were laid over a pain of glass? One thing that would be neat (outside of the challange) would be to crop the ball in Pshop and create 2-3 layers overlapping and each other. Set the layers'' opacity and this would give the ball the illusion of motion blur. Anyways, just a thought :) .... Hope you do well and I give this photo a 9</td>', 'Very creative point of view. The detail, composition, and DOF are excellent and the idea overall is simply brilliant. I''m assuming the bat and ball were laid over a pain of glass? One thing that would be neat (outside of the challange) would be to crop the ball in Pshop and create 2-3 layers overlapping and each other. Set the layers'' opacity and this would give the ball the illusion of motion blur. Anyways, just a thought :) .... Hope you do well and I give this photo a 9', '2004-06-08 03:44:08.000000', NULL, 1),
(754586, 80762, 20235, '<td valign="top">I like the color tone of this shot and the border you used.... very complimentary of each other.</td>', 'I like the color tone of this shot and the border you used.... very complimentary of each other.', '2004-06-08 03:45:39.000000', NULL, 1),
(754613, 80877, 21898, '<td valign="top">The B&amp;W and the angle come together to make this an interesting and clever shot. Especially like the sunlight reflecting off the ring, very clever :)</td>', 'The B&W and the angle come together to make this an interesting and clever shot. Especially like the sunlight reflecting off the ring, very clever :)', '2004-06-08 04:51:29.000000', NULL, 1),
(754614, 80281, 21898, '<td valign="top">Wow, the orange is very crisp against the blue of the sky. Good, interesting angle.</td>', 'Wow, the orange is very crisp against the blue of the sky. Good, interesting angle.', '2004-06-08 04:52:57.000000', NULL, 1),
(754615, 80872, 21898, '<td valign="top">Nice and dark- I love it. A good original idea.</td>', 'Nice and dark- I love it. A good original idea.', '2004-06-08 04:53:44.000000', NULL, 1),
(754616, 80685, 21898, '<td valign="top">Took me a while to work out what the sport was meant to be- I''m hoping it was skiing otherwise I''m completely flummoxed!</td>', 'Took me a while to work out what the sport was meant to be- I''m hoping it was skiing otherwise I''m completely flummoxed!', '2004-06-08 04:54:43.000000', NULL, 1),
(754617, 80841, 21898, '<td valign="top">Good idea, though I think the out-of-focus dart-ends (I always forget what they are actually called!) distract the eye from the focal point of the bulls-eye.</td>', 'Good idea, though I think the out-of-focus dart-ends (I always forget what they are actually called!) distract the eye from the focal point of the bulls-eye.', '2004-06-08 04:56:42.000000', NULL, 1),
