INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(754878, 80600, 15448, '<td valign="top">Lacking creativity</td>', 'Lacking creativity', '2004-06-08 12:11:50.000000', NULL, 1),
(754879, 80872, 15448, '<td valign="top">Gorgeous photo!</td>', 'Gorgeous photo!', '2004-06-08 12:11:58.000000', NULL, 1),
(754880, 80665, 15448, '<td valign="top">amazing</td>', 'amazing', '2004-06-08 12:12:04.000000', NULL, 1),
(754881, 79982, 15448, '<td valign="top">perfect</td>', 'perfect', '2004-06-08 12:12:13.000000', NULL, 1),
(754884, 80847, 15448, '<td valign="top">decent</td>', 'decent', '2004-06-08 12:12:24.000000', NULL, 1),
(754886, 80841, 7560, '<td valign="top">This is an amazingly well composed shot. Great DOF, great color.  My only problem, and it''s a doozy is that I can''t get darts wrapped into a team sport. I have the same problem with pool or card games. That drops you down to a 3. If this was any other challenge, this is an 8. Easy. This is a great shot, and please consider using it as a stock shot or making it a print. Very, very nice.</td>', 'This is an amazingly well composed shot. Great DOF, great color.  My only problem, and it''s a doozy is that I can''t get darts wrapped into a team sport. I have the same problem with pool or card games. That drops you down to a 3. If this was any other challenge, this is an 8. Easy. This is a great shot, and please consider using it as a stock shot or making it a print. Very, very nice.', '2004-06-08 12:13:05.000000', NULL, 1),
(754887, 80854, 7560, '<td valign="top">Good job getting a sport not normally considered a team sport into the challenge. :) Great DOF, and I like the way you have the golf ball positioned. I might have cleaned the pin, then again, I might not have. :) Very nice, 8</td>', 'Good job getting a sport not normally considered a team sport into the challenge. :) Great DOF, and I like the way you have the golf ball positioned. I might have cleaned the pin, then again, I might not have. :) Very nice, 8', '2004-06-08 12:14:27.000000', NULL, 1),
(754894, 80261, 7560, '<td valign="top">This is one of my 2 10s. Amazing shot. Love the leading lines across the ceiling, and withing the lockers. Great choice of tone for the image.  I''d like it better with all lockers having chairs in front of them. My question is how the heck did you get into the clubhouse? :) 10</td>', 'This is one of my 2 10s. Amazing shot. Love the leading lines across the ceiling, and withing the lockers. Great choice of tone for the image.  I''d like it better with all lockers having chairs in front of them. My question is how the heck did you get into the clubhouse? :) 10', '2004-06-08 12:17:10.000000', NULL, 1),
