(755775, 80442, 20375, '<td valign="top">Excellent idea.</td>', 'Excellent idea.', '2004-06-08 23:19:53.000000', NULL, 1),
(755777, 80825, 20375, '<td valign="top">Nostalgic. Fits challenge superbly.</td>', 'Nostalgic. Fits challenge superbly.', '2004-06-08 23:20:40.000000', NULL, 1),
(755781, 80485, 20375, '<td valign="top">I like it. Green filter though?<br/></td>', 'I like it. Green filter though?', '2004-06-08 23:23:37.000000', NULL, 1),
(755786, 80281, 20375, '<td valign="top">The soccer net shots weren''t my favourites, but the strength of the colour and the good exposure in this one, won me over. Well done.</td>', 'The soccer net shots weren''t my favourites, but the strength of the colour and the good exposure in this one, won me over. Well done.', '2004-06-08 23:24:46.000000', NULL, 1),
(755790, 80006, 20375, '<td valign="top">Good idea, well done you lost marks with me on the lousy background.<br/>I know, I''m being picky .... but it''s not the best.</td>', 'Good idea, well done you lost marks with me on the lousy background.I know, I''m being picky .... but it''s not the best.', '2004-06-08 23:26:15.000000', NULL, 1),
(755792, 80604, 20375, '<td valign="top">Good job. Back wall to the right of the shot is a bit blown out (overexposed)<br/>Still.......good idea.</td>', 'Good job. Back wall to the right of the shot is a bit blown out (overexposed)Still.......good idea.', '2004-06-08 23:27:15.000000', NULL, 1),
(755797, 80531, 20375, '<td valign="top">Mascot is slightly out of focus. Good job of capturing the spirit and excitement of attending a game.!!!!!!!!!</td>', 'Mascot is slightly out of focus. Good job of capturing the spirit and excitement of attending a game.!!!!!!!!!', '2004-06-08 23:29:03.000000', NULL, 1),
(755799, 80758, 20375, '<td valign="top">I know what you were going for here and it works! Good job.<br/>BUT!!!!!!!! <br/>My opinion is that you are showing or depicting players. You lost marks on that</td>', 'I know what you were going for here and it works! Good job.BUT!!!!!!!! My opinion is that you are showing or depicting players. You lost marks on that', '2004-06-08 23:32:22.000000', NULL, 1),
(755801, 80279, 20375, '<td valign="top">What is this?<br/></td>', 'What is this?', '2004-06-08 23:33:17.000000', NULL, 1),
(755802, 80776, 20375, '<td valign="top">Wasn''t a Kennedy killed playing this game?<br/></td>', 'Wasn''t a Kennedy killed playing this game?', '2004-06-08 23:33:55.000000', NULL, 1),
(755803, 80529, 20375, '<td valign="top">I appreciate your humor.</td>', 'I appreciate your humor.', '2004-06-08 23:34:40.000000', NULL, 1),
(755805, 80724, 20375, '<td valign="top">Not hot enough. Sorry. Good try but not a team sport. I know...others will argue.<br/>My opinion only...two people playing catch is not a team sport either.</td>', 'Not hot enough. Sorry. Good try but not a team sport. I know...others will argue.My opinion only...two people playing catch is not a team sport either.', '2004-06-08 23:36:29.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(755807, 80020, 20375, '<td valign="top">Too dark. Underexposed.  I believe a histogram will show this.</td>', 'Too dark. Underexposed.  I believe a histogram will show this.', '2004-06-08 23:37:09.000000', NULL, 1),
(755821, 80384, 8891, '<td valign="top">Nice set up and I like the used look of all the equipment. could be a bit brighter but the detail is very good throughout.</td>', 'Nice set up and I like the used look of all the equipment. could be a bit brighter but the detail is very good throughout.', '2004-06-08 23:45:11.000000', NULL, 1),
(755824, 80205, 18349, '<td valign="top">Excellent detail.  Weathered look really adds to the "feel."  One of my top 3 picks. :o)</td>', 'Excellent detail.  Weathered look really adds to the "feel."  One of my top 3 picks. :o)', '2004-06-08 23:50:00.000000', NULL, 1),
(755826, 80825, 18349, '<td valign="top">Great DOF, love the textures.  One of my top 3 picks.  :o)</td>', 'Great DOF, love the textures.  One of my top 3 picks.  :o)', '2004-06-08 23:50:31.000000', NULL, 1),
(755827, 80131, 18349, '<td valign="top">I had this exact same idea but couldn''t get it to look right.  You did! :o)  One of my top 3 picks, BTW.</td>', 'I had this exact same idea but couldn''t get it to look right.  You did! :o)  One of my top 3 picks, BTW.', '2004-06-08 23:51:16.000000', NULL, 1),
(755839, 80621, 8891, '<td valign="top">2 10''a from me  in this challenge...this is one of them.  The detail and overall shot is very effective and extremely well done, IMO.  AND you used two gloves which signifies a team to me (regardless of the fact that the glove(s) are obviously used in a team sport).  Great work!</td>', '2 10''a from me  in this challenge...this is one of them.  The detail and overall shot is very effective and extremely well done, IMO.  AND you used two gloves which signifies a team to me (regardless of the fact that the glove(s) are obviously used in a team sport).  Great work!', '2004-06-08 23:56:44.000000', NULL, 1),
(755841, 80281, 8891, '<td valign="top">One of my tens...now there is now suggestion of a team here but there is only one net at each end of the football(soccer) field so the it thoroughly meets the challenge for me.  The composition and detail is excellent and I very much like the abstractness of this image and the Great clouds and blue sky. Great work.</td>', 'One of my tens...now there is now suggestion of a team here but there is only one net at each end of the football(soccer) field so the it thoroughly meets the challenge for me.  The composition and detail is excellent and I very much like the abstractness of this image and the Great clouds and blue sky. Great work.', '2004-06-08 23:58:45.000000', NULL, 1),
(755843, 80239, 9809, '<td valign="top">One of my favorites of the challenge. You''ve stopped the action quite well -- I almost wish there was a little motion blur to show this is real. Colors, saturation, all great. Frame is nice without being obnoxious. Nicely done.</td>', 'One of my favorites of the challenge. You''ve stopped the action quite well -- I almost wish there was a little motion blur to show this is real. Colors, saturation, all great. Frame is nice without being obnoxious. Nicely done.', '2004-06-08 23:58:48.000000', NULL, 1),
(755844, 80442, 8891, '<td valign="top">I am not a fan of the big stuffed mascots, we have the obnoxious Phillie Phanatic...what a mess that is.  I ranked this fairly high because of the shot. I love how the mascot stands out so finely against everything in the backgrround and the foreground AND the great colors.  Excellent.</td>', 'I am not a fan of the big stuffed mascots, we have the obnoxious Phillie Phanatic...what a mess that is.  I ranked this fairly high because of the shot. I love how the mascot stands out so finely against everything in the backgrround and the foreground AND the great colors.  Excellent.', '2004-06-09 00:00:45.000000', NULL, 1),
(755847, 80485, 9809, '<td valign="top">I''ve seen many an empty playing field in this challenge, but this is the best to me. The green tint really works and the overall monochromatic look of most of the photo with the goal and tree nearby standing out from the rest -- looking almost 3D is what makes this one better than the rest. Nicely done.</td>', 'I''ve seen many an empty playing field in this challenge, but this is the best to me. The green tint really works and the overall monochromatic look of most of the photo with the goal and tree nearby standing out from the rest -- looking almost 3D is what makes this one better than the rest. Nicely done.', '2004-06-09 00:01:33.000000', NULL, 1),
(755850, 80851, 8891, '<td valign="top">This image is more about the fans than a sport or team. But it is obvious that the seats are in some sort of stadium for some sort of sport, team or otherwise. I like it very much.. It is finely shot and works for me.</td>', 'This image is more about the fans than a sport or team. But it is obvious that the seats are in some sort of stadium for some sort of sport, team or otherwise. I like it very much.. It is finely shot and works for me.', '2004-06-09 00:02:53.000000', NULL, 1),
(755866, 80525, 8891, '<td valign="top">i like this very much and wish that you could have shot this without any of the people on the left of the horizon or the lifeguard house at the right behind the net.  Dang old no spot editing rules.</td>', 'i like this very much and wish that you could have shot this without any of the people on the left of the horizon or the lifeguard house at the right behind the net.  Dang old no spot editing rules.', '2004-06-09 00:26:41.000000', NULL, 1),
(755873, 79488, 1054, '<td valign="top">Shea Stadium?</td>', 'Shea Stadium?', '2004-06-09 00:31:52.000000', NULL, 1),
(755880, 80844, 20889, '<td valign="top">Looks well used :-))</td>', 'Looks well used :-))', '2004-06-09 00:38:53.000000', NULL, 1),
(755894, 80451, 1054, '<td valign="top">Nice abstract... I like this shot.</td>', 'Nice abstract... I like this shot.', '2004-06-09 00:54:25.000000', NULL, 1),
(755898, 79809, 1054, '<td valign="top">Nice play on words... and I like the shot too!</td>', 'Nice play on words... and I like the shot too!', '2004-06-09 00:56:43.000000', NULL, 1),
(755907, 80261, 12962, '<td valign="top">Congratulations!  I am so glad that this pulled through ... even with the two ones (why oh why is that?).</td>', 'Congratulations!  I am so glad that this pulled through ... even with the two ones (why oh why is that?).', '2004-06-09 01:01:25.000000', NULL, 0),
(755911, 80490, 18349, '<td valign="top">Hey, thanks everyone for your comments during the challenge.  I had high hopes for this one, but I guess hot glue wasn''t such a good idea after all!  :o) LOL</td>', 'Hey, thanks everyone for your comments during the challenge.  I had high hopes for this one, but I guess hot glue wasn''t such a good idea after all!  :o) LOL', '2004-06-09 01:04:24.000000', NULL, 0),
